#include <stddef.h>
#include <stdio.h>

static int address_probe(void) {
  void *return_address = __builtin_return_address(0);
  void *frame_address  = __builtin_frame_address(0);
  return (return_address != NULL) + (frame_address != NULL);
}

int main(void) {
  printf("%d\n", address_probe());
  return 0;
}



